    const bool int8 = pools.k_q != nullptr;
    if (int8 ? (!pools.v_q || !pools.k_scale || !pools.v_scale) : (!pools.k_pool || !pools.v_pool)) {
        std::fprintf(stderr, "qsa_decode_attn: incomplete KV pools\n");
